<template>
  <section class="search-replace-preview" aria-label="替换 Diff 预览">
    <div class="replace-review-actions"><strong>替换预览</strong><button :disabled="workspace.replaceBusy" @click="workspace.selectReplacements(true)">全选</button><button :disabled="workspace.replaceBusy" @click="workspace.selectReplacements(false)">取消全选</button><button :disabled="workspace.replaceBusy||!selected" @click="workspace.applyReplacements()">应用预览中选择的替换</button><button @click="workspace.cancelReplace()">{{workspace.replaceApplying?'取消未执行文件':'取消预览'}}</button></div>
    <p role="status">{{workspace.replaceMessage}}</p><p v-if="workspace.replaceApplying">进度 {{workspace.replaceProgress}} / {{workspace.replaceFiles.filter(file=>file.selected.size).length}} 文件</p>
    <div v-for="file in workspace.replaceFiles" :key="file.path" class="replace-review-file">
      <div class="replace-review-file-head"><input type="checkbox" :disabled="workspace.replaceBusy||!!file.status" :aria-label="`选择替换文件 ${file.path}`" :checked="file.selected.size===file.edits.length" :indeterminate="file.selected.size>0&&file.selected.size<file.edits.length" @change="workspace.selectReplacements(($event.target as HTMLInputElement).checked,file.path)" /><button @click="file.expanded=!file.expanded">{{file.expanded?'−':'+'}} {{relative(file.path)}}</button><span>{{file.status||`${file.selected.size}/${file.edits.length}`}}</span></div>
      <template v-if="file.expanded"><label v-for="(edit,index) in file.edits" :key="`${edit.from}:${edit.to}`" class="replace-review-edit"><input type="checkbox" :disabled="workspace.replaceBusy||!!file.status" :checked="file.selected.has(index)" :aria-label="`替换 ${relative(file.path)}:${edit.line}:${edit.column}`" @change="workspace.toggleReplacement(file,index)" /><span class="replace-review-diff"><small>{{edit.line}}:{{edit.column}} · {{edit.context}}</small><del><b aria-hidden="true">− </b>{{edit.before.slice(0,2000)||'（零宽匹配）'}}{{edit.before.length>2000?'…':''}}</del><ins><b aria-hidden="true">+ </b>{{edit.insert.slice(0,2000)||'（删除）'}}{{edit.insert.length>2000?'…':''}}</ins></span></label></template>
    </div>
  </section>
</template>
<script setup lang="ts">
import {computed} from 'vue'
import type {WorkspaceController} from '../../features/workspace/WorkspaceController'
const props=defineProps<{workspace:WorkspaceController}>()
const selected=computed(()=>props.workspace.replaceFiles.some(file=>file.selected.size&&!file.status))
function relative(path:string){return props.workspace.searchResults.find(group=>group.path===path)?.relativePath||path.split(/[\\/]/).slice(-2).join('/')}
</script>
<style scoped>.search-replace-preview{height:100%;overflow:auto;padding:8px 12px;font-size:var(--ui-small-font-size);box-sizing:border-box}.replace-review-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap;position:sticky;top:0;background:var(--editor);padding:4px 0}.replace-review-actions button{padding:4px 7px;background:var(--soft);border-radius:4px}.replace-review-file-head{display:flex;align-items:center;gap:7px;padding:6px 0;border-top:1px solid var(--line)}.replace-review-file-head button{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left;flex:1}.replace-review-file-head span{color:var(--sub)}.replace-review-edit{display:flex;align-items:flex-start;gap:8px;padding:5px 0}.replace-review-diff{display:grid;min-width:0;width:100%;font-family:var(--font-mono);white-space:pre-wrap;overflow-wrap:anywhere}.replace-review-diff small{color:var(--muted);padding:2px 5px}.replace-review-diff del,.replace-review-diff ins{padding:2px 5px;text-decoration:none}.replace-review-diff del{background:color-mix(in srgb,var(--red,#ca5050) 15%,transparent)}.replace-review-diff ins{background:color-mix(in srgb,var(--green,#379660) 15%,transparent)}p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}</style>
